#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int maxEqualFreq(vector<int>& nums) {
        vector<int> count(100001, 0);
        vector<int> frequency(nums.size() + 1, 0);
        int maxFreq = 0;
        int answer = 0;

        for (int i = 0; i < static_cast<int>(nums.size()); ++i) {
            int x = nums[i];
            if (count[x] > 0) {
                --frequency[count[x]];
            }
            ++count[x];
            ++frequency[count[x]];
            maxFreq = max(maxFreq, count[x]);

            int length = i + 1;

            bool allOnce = maxFreq == 1;
            bool removeSingleton =
                frequency[1] == 1 &&
                maxFreq * frequency[maxFreq] + 1 == length;
            bool reduceMaximum =
                frequency[maxFreq] == 1 &&
                maxFreq + (maxFreq - 1) * frequency[maxFreq - 1] == length;

            if (allOnce || removeSingleton || reduceMaximum) {
                answer = length;
            }
        }

        return answer;
    }
};

